begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('member-family-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','member-family-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','family-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,full_name,status,birth_date) select pg_temp.fi(t),pg_temp.fi('org'),pg_temp.fi('a'),t||' criança fictícia','active',current_date-interval '7 years' from unnest(array['child','otherchild'])t;
insert into private.kids_profiles(id,organization_id,unit_id,person_id,review_status,created_by) select pg_temp.fi(t||'-profile'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),'approved',pg_temp.fi('owner') from unnest(array['child','otherchild'])t;
insert into private.kids_guardians(organization_id,unit_id,profile_id,person_id,relationship,verification_note,can_pickup,can_edit,status,approved_by,approved_at,created_by) select pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t||'-profile'),pg_temp.fi(case when t='child' then 'member-person' else 'second-person' end),'Responsável','Conferência fictícia',true,true,'approved',pg_temp.fi('owner'),now(),pg_temp.fi('owner') from unnest(array['child','otherchild'])t;
insert into private.kids_care(profile_id,organization_id,unit_id,instructions,source) values(pg_temp.fi('child-profile'),pg_temp.fi('org'),pg_temp.fi('a'),'Cuidados privados fictícios','Responsável fictício');
insert into private.kids_rooms(id,organization_id,unit_id,name,location,capacity) values(pg_temp.fi('room'),pg_temp.fi('org'),pg_temp.fi('a'),'Sala fictícia','Local interno',1);
insert into private.kids_classes(id,organization_id,unit_id,name,min_months,max_months) values(pg_temp.fi('class'),pg_temp.fi('org'),pg_temp.fi('a'),'Turma fictícia',0,215);
insert into private.kids_sessions(id,organization_id,unit_id,name,starts_at,ends_at,status,created_by) values(pg_temp.fi('session'),pg_temp.fi('org'),pg_temp.fi('a'),'Sessão fictícia',now()-interval '10 minutes',now()+interval '2 hours','open',pg_temp.fi('owner'));
insert into private.kids_session_rooms(id,organization_id,unit_id,session_id,room_id,class_id,capacity,min_staff) values(pg_temp.fi('group'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('session'),pg_temp.fi('room'),pg_temp.fi('class'),1,1);
insert into private.kids_assignments(id,organization_id,unit_id,session_id,group_id,person_id,member_id,role) values(pg_temp.fi('assignment'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('session'),pg_temp.fi('group'),pg_temp.fi('owner-person'),pg_temp.fi('owner-membership'),'teacher');
insert into public.church_cells(id,organization_id,unit_id,name,meeting_day,meeting_time,meeting_format,location,created_by) select pg_temp.fi(t),pg_temp.fi('org'),pg_temp.fi(case when t='cellb' then 'b' else 'a' end),t||' grupo fictício',2,'19:30','presential','Endereço privado de uma família',pg_temp.fi('owner') from unnest(array['cell','hidden','cellb'])t;
insert into private.cell_app_publications(cell_id,organization_id,unit_id,area,description,published,updated_by) select pg_temp.fi(t),pg_temp.fi('org'),pg_temp.fi(case when t='cellb' then 'b' else 'a' end),'Região pública fictícia','Descrição para divulgação',true,pg_temp.fi('owner') from unnest(array['cell','cellb'])t;
insert into private.cell_study_materials(id,organization_id,unit_id,title,body,status,created_by) select pg_temp.fi(t),pg_temp.fi('org'),pg_temp.fi('a'),t,'Material fictício',case when t='material' then 'published' else 'draft' end,pg_temp.fi('owner') from unnest(array['material','draft'])t;
create function pg_temp.self(a text,i uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_family(pg_temp.fi('org'),pg_temp.fi('a'),a,i,v,d)$$;
create function pg_temp.admin(a text,i uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_family_admin(pg_temp.fi('org'),pg_temp.fi('a'),a,i,v,d)$$;
create function pg_temp.request_id(t text) returns uuid language sql security definer as $$select id from private.member_family_requests where organization_id=pg_temp.fi('org') and nonce=t$$;
create function pg_temp.booking() returns uuid language sql security definer as $$select id from private.kids_member_reservations where profile_id=pg_temp.fi('child-profile')$$;
create function pg_temp.referral() returns uuid language sql security definer as $$select id from private.cell_referrals where cell_id=pg_temp.fi('cell') and person_id=pg_temp.fi('member-person')$$;
select ok(not has_table_privilege('authenticated','private.member_family_requests','select'),'solicitações sem leitura direta');
select ok(not has_function_privilege('anon','public.member_family(uuid,uuid,text,uuid,integer,jsonb,integer)','execute'),'visitante não consulta famílias');
select pg_temp.actor('unconfirmed');set local role authenticated;
select throws_ok($$select pg_temp.self('kids.list')$$,'42501',null,'e-mail não confirmado bloqueado');
reset role;select pg_temp.actor('outside');set local role authenticated;
select throws_ok($$select pg_temp.self('kids.list')$$,'42501','community_denied','outro ministério bloqueado');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(jsonb_array_length(pg_temp.self('kids.list')->'children'),1,'responsável vê apenas criança autorizada');
select is(pg_temp.self('kids.list')->'children'->0->>'care','Cuidados privados fictícios','responsável com edição consulta orientações atuais');
select throws_ok($$select pg_temp.self('kids.sessions',pg_temp.fi('otherchild-profile'))$$,'42501','family_denied','não consulta sessão em nome de outra criança');
select is(jsonb_array_length(pg_temp.self('kids.sessions',pg_temp.fi('child-profile'))->'items'),1,'sessão compatível aparece');
select lives_ok($$select pg_temp.self('kids.reserve',pg_temp.fi('group'),null,jsonb_build_object('profile',pg_temp.fi('child-profile')))$$,'registra reserva');
select lives_ok($$select pg_temp.self('kids.reserve',pg_temp.fi('group'),null,jsonb_build_object('profile',pg_temp.fi('child-profile')))$$,'repetição de reserva não duplica');
select is(jsonb_array_length(pg_temp.self('kids.list')->'reservations'),1,'uma reserva por criança e sessão');
select is(pg_temp.self('kids.list')->'reservations'->0->>'attendance',null,'reserva não cria entrada');
select throws_ok($$select pg_temp.self('kids.pickup',pg_temp.booking(),1)$$,'40001','family_not_present','não pede retirada antes da entrada');
select throws_ok($$select pg_temp.admin('kids.requests')$$,'42501','family_denied','membro não revisa solicitações');
select lives_ok($$select pg_temp.self('kids.create',null,null,jsonb_build_object('nonce','new-child-fixture','name','Nova criança fictícia','birth',(current_date-interval '5 years')::date,'care','Cuidado fictício para conferência'))$$,'envia criança para revisão');
select lives_ok($$select pg_temp.self('kids.create',null,null,jsonb_build_object('nonce','new-child-fixture','name','Nova criança fictícia','birth',(current_date-interval '5 years')::date,'care','Cuidado fictício para conferência'))$$,'reenvio da solicitação é idempotente');
select is(jsonb_array_length(pg_temp.self('kids.list')->'children'),1,'envio não cria vínculo autorizado');
select is(jsonb_array_length(pg_temp.self('kids.list')->'requests'),1,'solicitação única visível ao autor');
select lives_ok($$select pg_temp.self('kids.edit',pg_temp.fi('child-profile'),null,jsonb_build_object('nonce','child-edit-stale','name','child criança fictícia','birth',(current_date-interval '7 years')::date,'care','Orientação anterior enviada para revisão'))$$,'responsável solicita alteração sem reescrever o cadastro');
select is(jsonb_array_length(pg_temp.self('cells.list')->'items'),1,'busca mostra somente grupos publicados da igreja');
select is(pg_temp.self('cells.list')->'items'->0->>'location','','endereço particular não é divulgado na busca');
select is(jsonb_array_length(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'materials'),0,'material de grupo exige participação');
select lives_ok($$select pg_temp.self('cells.join',pg_temp.fi('cell'))$$,'solicita participação via indicação integrada');
select lives_ok($$select pg_temp.self('cells.join',pg_temp.fi('cell'))$$,'clique repetido não duplica indicação');
select is(jsonb_array_length(pg_temp.self('cells.list')->'requests'),1,'indicação única no aplicativo');
select throws_ok($$select pg_temp.self('cells.join',pg_temp.fi('hidden'))$$,'42501','family_denied','grupo não publicado não aceita autoinscrição');
select throws_ok($$select pg_temp.self('cells.join',pg_temp.fi('cellb'))$$,'42501','family_denied','inscrição não atravessa igrejas');
reset role;select pg_temp.actor('second');set local role authenticated;
select is(jsonb_array_length(pg_temp.self('kids.list')->'requests'),0,'outra conta não vê solicitação infantil');
select is(jsonb_array_length(pg_temp.self('kids.list')->'reservations'),0,'outra família não vê reservas');
select throws_ok($$select pg_temp.self('kids.reserve',pg_temp.fi('group'),null,jsonb_build_object('profile',pg_temp.fi('otherchild-profile')))$$,'40001','family_full','última vaga reservada não é vendida duas vezes');
select throws_ok($$select pg_temp.self('request.cancel',pg_temp.request_id('new-child-fixture'),1)$$,'42501','family_denied','outra conta não cancela pedido');
reset role;select pg_temp.actor('owner');set local role authenticated;
select is(public.kids_operations_page(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('session'))->'groups'->0->>'reserved','1','painel presencial considera a reserva da família');
select throws_ok($$select public.kids_operations_save(pg_temp.fi('org'),pg_temp.fi('a'),extensions.gen_random_uuid(),'checkin',pg_temp.fi('unreserved-attendance'),0,jsonb_build_object('sessionId',pg_temp.fi('session'),'groupId',pg_temp.fi('group'),'profileId',pg_temp.fi('otherchild-profile'),'guardianId',pg_temp.fi('second-person'),'identityConfirmed',true,'receiptSecret',repeat('a',64)))$$,'40001','kids_reserved_capacity','entrada sem reserva não ocupa a vaga de outra família');
select is(jsonb_array_length(pg_temp.admin('kids.requests')->'items'),2,'gestão autorizada revisa pedidos');
select throws_ok($$select pg_temp.admin('kids.review',pg_temp.request_id('new-child-fixture'),1,'{"decision":"approved","reason":"Cadastro fictício conferido","verification":"","existingProfile":""}')$$,'22023','family_verification_required','aprovação exige conferência documentada');
select lives_ok($$select pg_temp.admin('kids.review',pg_temp.request_id('new-child-fixture'),1,'{"decision":"approved","reason":"Cadastro fictício conferido","verification":"Vínculo e identidade conferidos em homologação fictícia","existingProfile":""}')$$,'aprovação cria Pessoas, perfil e responsável conferido');
reset role;
update private.kids_care set instructions='Orientação mais recente da equipe',version=version+1 where profile_id=pg_temp.fi('child-profile');
select pg_temp.actor('owner');set local role authenticated;
select throws_ok($$select pg_temp.admin('kids.review',pg_temp.request_id('child-edit-stale'),1,'{"decision":"approved","reason":"Revisão fictícia","verification":"Conferência fictícia documentada","existingProfile":""}')$$,'40001','family_changed','pedido antigo não sobrescreve cuidados atualizados pela equipe');
select throws_ok($$select pg_temp.admin('kids.review',pg_temp.request_id('new-child-fixture'),1,'{"decision":"rejected","reason":"Reenvio antigo","verification":"","existingProfile":""}')$$,'40001','family_changed','versão antiga não sobrescreve revisão');
select lives_ok($$select public.cell_plus_save(pg_temp.fi('org'),pg_temp.fi('a'),'accept_referral',pg_temp.referral(),1,'{}')$$,'painel existente aprova participação');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(jsonb_array_length(pg_temp.self('kids.list')->'children'),2,'criança aprovada sincroniza no aplicativo');
select is(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'items'->0->>'joined','true','participação aprovada sincroniza');
select is(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'items'->0->>'location','Endereço privado de uma família','participante vê localização do próprio grupo');
select is(jsonb_array_length(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'materials'),1,'somente material publicado disponível ao participante');
select lives_ok($$select pg_temp.self('cells.leave',pg_temp.fi('cell'),null,'{"nonce":"exit-fixture-request"}')$$,'saída é enviada para revisão');
select is(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'items'->0->>'joined','true','solicitação de saída não altera vínculo sozinha');
reset role;select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.admin('cells.review',pg_temp.request_id('exit-fixture-request'),1,'{"decision":"approved","reason":"Saída fictícia revisada","verification":"","existingProfile":""}')$$,'gestão aprova saída mantendo histórico');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'items'->0->>'joined','false','saída aprovada sincroniza participação');
select is(jsonb_array_length(pg_temp.self('cells.detail',pg_temp.fi('cell'))->'materials'),0,'saída encerra leitura de materiais reservados');
select lives_ok($$select pg_temp.self('kids.cancel',pg_temp.booking(),1)$$,'responsável cancela reserva');
select throws_ok($$select pg_temp.self('kids.cancel',pg_temp.booking(),1)$$,'40001','family_changed','versão antiga de reserva recusada');
select lives_ok($$select pg_temp.self('kids.reserve',pg_temp.fi('group'),null,jsonb_build_object('profile',pg_temp.fi('child-profile')))$$,'cancelamento libera nova reserva');
reset role;select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select public.kids_operations_save(pg_temp.fi('org'),pg_temp.fi('a'),extensions.gen_random_uuid(),'checkin',pg_temp.fi('attendance'),0,jsonb_build_object('sessionId',pg_temp.fi('session'),'groupId',pg_temp.fi('group'),'profileId',pg_temp.fi('child-profile'),'guardianId',pg_temp.fi('member-person'),'identityConfirmed',true,'receiptSecret',repeat('a',64)))$$,'equipe recebe fisicamente criança reservada');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(pg_temp.self('kids.list')->'presence'->0->>'status','present','responsável acompanha entrada confirmada');
select lives_ok($$select pg_temp.self('kids.pickup',pg_temp.booking(),3)$$,'responsável solicita retirada à recepção');
select is(pg_temp.self('kids.list')->'presence'->0->>'status','present','solicitar retirada não encerra custódia');
select throws_ok($$select pg_temp.self('kids.cancel',pg_temp.booking(),4)$$,'40001','family_already_received','reserva recebida não pode ser cancelada pelo aplicativo');
reset role;select pg_temp.actor('owner');set local role authenticated;
select is(jsonb_array_length(pg_temp.admin('kids.reception')->'items'),1,'pedido de retirada aparece à gestão da recepção');
select is(public.kids_operations_page(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('session'))->'groups'->0->>'reserved','0','criança recebida não é contada duas vezes na ocupação');
select lives_ok($$select public.kids_operations_save(pg_temp.fi('org'),pg_temp.fi('a'),extensions.gen_random_uuid(),'checkout',pg_temp.fi('attendance'),1,jsonb_build_object('guardianId',pg_temp.fi('member-person'),'identityConfirmed',true,'receiptSecret',repeat('a',64)))$$,'retirada continua exigindo equipe e comprovante');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(pg_temp.self('kids.list')->'presence'->0->>'status','out','retirada conferida sincroniza no aplicativo');
reset role;
select is((select count(*)::integer from public.people where organization_id=pg_temp.fi('org') and full_name='Nova criança fictícia'),1,'sem duplicar cadastro mestre');
select ok(not exists(select 1 from public.audit_logs where organization_id=pg_temp.fi('org') and metadata::text like '%Cuidado fictício%'),'auditoria não inclui cuidados privados');
select * from finish();rollback;
